import 'package:flutter/material.dart'; import 'package:flutter_map/flutter_map.dart'; import 'package:latlong2/latlong.dart'; import 'package:sheshield/models/safety_report.dart'; import 'package:sheshield/services/location_service.dart'; import 'package:sheshield/services/safety_report_service.dart'; import 'package:sheshield/services/auth_service.dart';
class SafetyHeatMapScreen extends StatefulWidget{const SafetyHeatMapScreen({super.key});@override State<SafetyHeatMapScreen> createState()=>_SafetyHeatMapScreenState();}
class _SafetyHeatMapScreenState extends State<SafetyHeatMapScreen>{late Future<List<SafetyReport>> reports;@override void initState(){super.initState();reports=SafetyReportService().list();} Color color(String c)=>switch(c){'HARASSMENT'=>Colors.red,'STALKING'=>Colors.deepOrange,'DARK_AREA'=>Colors.purple,'UNSAFE_ROAD'=>Colors.orange,'ISOLATED_LOCATION'=>Colors.indigo,_=>Colors.brown};Future<void> add()async{final loc=TextEditingController(),desc=TextEditingController();String cat='HARASSMENT';double? lat,lon;try{final p=await LocationService().getCurrentPosition();lat=p.latitude;lon=p.longitude;}catch(_){}if(!mounted)return;final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('Anonymous Unsafe Location Report'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:loc,decoration:const InputDecoration(labelText:'Location name')),const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:cat,items:const ['HARASSMENT','STALKING','DARK_AREA','UNSAFE_ROAD','ISOLATED_LOCATION','PREVIOUS_INCIDENT'].map((v)=>DropdownMenuItem(value:v,child:Text(v.replaceAll('_',' ')))).toList(),onChanged:(v)=>set(()=>cat=v!),decoration:const InputDecoration(labelText:'Category')),const SizedBox(height:10),TextField(controller:desc,maxLines:3,decoration:const InputDecoration(labelText:'Description')),const SizedBox(height:8),Text(lat==null?'GPS unavailable':'GPS: $lat, $lon')])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Submit'))])));if(ok!=true||lat==null||lon==null)return;try{await SafetyReportService().create(location:loc.text.trim().isEmpty?'Current location':loc.text.trim(),latitude:lat,longitude:lon,category:cat,description:desc.text.trim().isEmpty?'Unsafe location reported anonymously':desc.text.trim());if(mounted)setState(()=>reports=SafetyReportService().list());}on AuthException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Campus Safety Heat Map')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add_location_alt),label:const Text('Report')),body:FutureBuilder<List<SafetyReport>>(future:reports,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final data=s.data!;final center=data.isEmpty?const LatLng(11.0168,76.9558):LatLng(data.first.latitude,data.first.longitude);return FlutterMap(options:MapOptions(initialCenter:center,initialZoom:14),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.example.sheshield'),CircleLayer(circles:data.map((r)=>CircleMarker(point:LatLng(r.latitude,r.longitude),radius:35,color:color(r.category).withValues(alpha:.38),borderColor:color(r.category),borderStrokeWidth:2)).toList()),MarkerLayer(markers:data.map((r)=>Marker(point:LatLng(r.latitude,r.longitude),width:44,height:44,child:Tooltip(message:'${r.category.replaceAll('_',' ')}\n${r.location}\n${r.description}',child:Icon(Icons.warning_rounded,color:color(r.category),size:34)))).toList()),RichAttributionWidget(attributions:[TextSourceAttribution('OpenStreetMap contributors')])]);}));}
